# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


class SeatingRowTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            Student("1", "Halloway", "Juno", "A"),
            Student("2", "Dunmere", "Piet", "A"),
            Student("3", "Quillon", "Sefa", "A"),
        ]

    def test_sorts_by_last_name_and_fills_rows_left_to_right(self):
        self.assertEqual(
            seating_rows(self.students, 2),
            ["Row 1: Dunmere, Piet | Halloway, Juno", "Row 2: Quillon, Sefa"],
        )

    def test_exact_fit_gives_one_row(self):
        rows = seating_rows(self.students, 3)
        self.assertEqual(
            rows, ["Row 1: Dunmere, Piet | Halloway, Juno | Quillon, Sefa"]
        )

    def test_ties_on_last_name_break_on_first_name(self):
        pair = [
            Student("4", "Smith", "Zoe", "A"),
            Student("5", "Smith", "Adam", "A"),
        ]
        self.assertEqual(seating_rows(pair, 2), ["Row 1: Smith, Adam | Smith, Zoe"])

    def test_accepts_any_iterable_of_students(self):
        rows = seating_rows(iter(self.students), 1)
        self.assertEqual(len(rows), 3)

    def test_zero_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -2)

    def test_no_students_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
